'use server'

import { createClient } from '@/lib/supabase/server'
import type {
  Formation,
    Module,
      FormationComplete,
      } from '@/lib/types/formation'

      // =====================================================
      // TYPES DE RETOUR
      // =====================================================

      export type ActionResult<T = void> =
        | { success: true; data: T }
          | { success: false; error: string }

          // =====================================================
          // FORMATIONS — CRUD
          // =====================================================

          /** Récupère toutes les formations (admin/gestionnaire) */
          export async function getFormations(): Promise<ActionResult<Formation[]>> {
            const supabase = await createClient()
              const { data: { user } } = await supabase.auth.getUser()
                if (!user) return { success: false, error: 'Non authentifié' }

                  const { data, error } = await supabase
                      .from('formations')
                          .select('*')
                              .order('created_at', { ascending: false })

                                if (error) return { success: false, error: error.message }
                                  return { success: true, data: data as Formation[] }
                                  }

                                  /** Récupère une formation avec ses modules */
                                  export async function getFormationWithModules(
                                    formationId: string
                                    ): Promise<ActionResult<FormationComplete>> {
                                      const supabase = await createClient()
                                        const { data: { user } } = await supabase.auth.getUser()
                                          if (!user) return { success: false, error: 'Non authentifié' }

                                            const { data, error } = await supabase
                                                .from('formations')
                                                    .select(`
                                                          *,
                                                                modules (
                                                                        *,
                                                                                lessons (
                                                                                          *,
                                                                                                    content_blocks (*)
                                                                                                            )
                                                                                                                  )
                                                                                                                      `)
                                                                                                                          .eq('id', formationId)
                                                                                                                              .order('ordre', { referencedTable: 'modules', ascending: true })
                                                                                                                                  .single()
                                                                                                                                  
                                                                                                                                    if (error) return { success: false, error: error.message }
                                                                                                                                      return { success: true, data: data as FormationComplete }
                                                                                                                                      }
                                                                                                                                      
                                                                                                                                      /** Crée une nouvelle formation */
                                                                                                                                      export async function createFormation(
                                                                                                                                        payload: {
                                                                                                                                            titre: string
                                                                                                                                                description?: string
                                                                                                                                                    categorie?: string
                                                                                                                                                        niveau?: 'debutant' | 'intermediaire' | 'avance'
                                                                                                                                                            duree_estimee_minutes?: number
                                                                                                                                                              }
                                                                                                                                                              ): Promise<ActionResult<Formation>> {
                                                                                                                                                                const supabase = await createClient()
                                                                                                                                                                  const { data: { user } } = await supabase.auth.getUser()
                                                                                                                                                                    if (!user) return { success: false, error: 'Non authentifié' }
                                                                                                                                                                    
                                                                                                                                                                      // Vérifier rôle admin/gestionnaire
                                                                                                                                                                        const { data: employe } = await supabase
                                                                                                                                                                            .from('employes')
                                                                                                                                                                                .select('role')
                                                                                                                                                                                    .eq('auth_user_id', user.id)
                                                                                                                                                                                        .single()
                                                                                                                                                                                        
                                                                                                                                                                                          if (!employe || !['admin', 'gestionnaire'].includes(employe.role)) {
                                                                                                                                                                                              return { success: false, error: 'Permission refusée' }
                                                                                                                                                                                                }
                                                                                                                                                                                                
                                                                                                                                                                                                  const { data, error } = await supabase
                                                                                                                                                                                                      .from('formations')
                                                                                                                                                                                                          .insert({ ...payload, publiee: false })
                                                                                                                                                                                                              .select()
                                                                                                                                                                                                                  .single()
                                                                                                                                                                                                                  
                                                                                                                                                                                                                    if (error) return { success: false, error: error.message }
                                                                                                                                                                                                                      return { success: true, data: data as Formation }
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                      
                                                                                                                                                                                                                      /** Met à jour une formation */
                                                                                                                                                                                                                      export async function updateFormation(
                                                                                                                                                                                                                        formationId: string,
                                                                                                                                                                                                                          payload: Partial<{
                                                                                                                                                                                                                              titre: string
                                                                                                                                                                                                                                  description: string
                                                                                                                                                                                                                                      categorie: string
                                                                                                                                                                                                                                          niveau: 'debutant' | 'intermediaire' | 'avance'
                                                                                                                                                                                                                                              duree_estimee_minutes: number
                                                                                                                                                                                                                                                  publiee: boolean
                                                                                                                                                                                                                                                    }>
                                                                                                                                                                                                                                                    ): Promise<ActionResult<Formation>> {
                                                                                                                                                                                                                                                      const supabase = await createClient()
                                                                                                                                                                                                                                                        const { data: { user } } = await supabase.auth.getUser()
                                                                                                                                                                                                                                                          if (!user) return { success: false, error: 'Non authentifié' }
                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                            const { data: employe } = await supabase
                                                                                                                                                                                                                                                                .from('employes')
                                                                                                                                                                                                                                                                    .select('role')
                                                                                                                                                                                                                                                                        .eq('auth_user_id', user.id)
                                                                                                                                                                                                                                                                            .single()
                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                              if (!employe || !['admin', 'gestionnaire'].includes(employe.role)) {
                                                                                                                                                                                                                                                                                  return { success: false, error: 'Permission refusée' }
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                      const { data, error } = await supabase
                                                                                                                                                                                                                                                                                          .from('formations')
                                                                                                                                                                                                                                                                                              .update(payload)
                                                                                                                                                                                                                                                                                                  .eq('id', formationId)
                                                                                                                                                                                                                                                                                                      .select()
                                                                                                                                                                                                                                                                                                          .single()
                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                            if (error) return { success: false, error: error.message }
                                                                                                                                                                                                                                                                                                              return { success: true, data: data as Formation }
                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                              /** Publie ou dépublie une formation */
                                                                                                                                                                                                                                                                                                              export async function togglePublierFormation(
                                                                                                                                                                                                                                                                                                                formationId: string,
                                                                                                                                                                                                                                                                                                                  publiee: boolean
                                                                                                                                                                                                                                                                                                                  ): Promise<ActionResult<Formation>> {
                                                                                                                                                                                                                                                                                                                    return updateFormation(formationId, { publiee })
                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                    /** Supprime une formation */
                                                                                                                                                                                                                                                                                                                    export async function deleteFormation(
                                                                                                                                                                                                                                                                                                                      formationId: string
                                                                                                                                                                                                                                                                                                                      ): Promise<ActionResult> {
                                                                                                                                                                                                                                                                                                                        const supabase = await createClient()
                                                                                                                                                                                                                                                                                                                          const { data: { user } } = await supabase.auth.getUser()
                                                                                                                                                                                                                                                                                                                            if (!user) return { success: false, error: 'Non authentifié' }
                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                              const { data: employe } = await supabase
                                                                                                                                                                                                                                                                                                                                  .from('employes')
                                                                                                                                                                                                                                                                                                                                      .select('role')
                                                                                                                                                                                                                                                                                                                                          .eq('auth_user_id', user.id)
                                                                                                                                                                                                                                                                                                                                              .single()
                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                if (!employe || employe.role !== 'admin') {
                                                                                                                                                                                                                                                                                                                                                    return { success: false, error: 'Seul un admin peut supprimer une formation' }
                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                        const { error } = await supabase
                                                                                                                                                                                                                                                                                                                                                            .from('formations')
                                                                                                                                                                                                                                                                                                                                                                .delete()
                                                                                                                                                                                                                                                                                                                                                                    .eq('id', formationId)
                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                      if (error) return { success: false, error: error.message }
                                                                                                                                                                                                                                                                                                                                                                        return { success: true, data: undefined }
                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                        // =====================================================
