                                                                                                                                                                                                                                                                                                                                                                                              duree_minutes?: number
                                                                                                                                                                                                                                                                                                                                                                                                  contenu?: string
                                                                                                                                                                                                                                                                                                                                                                                                      video_url?: string
                                                                                                                                                                                                                                                                                                                                                                                                          fichier_url?: string
