                                                                                                                                                                                                                                                                                                                                                                                                                                                                              description: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ordre: number
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      duree_minutes: number
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          contenu: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              video_url: string
