                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              /** Supprime un module (et ses leçons en cascade) */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export async function deleteModule(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                moduleId: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ): Promise<ActionResult> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const supabase = await createClient()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const { data: { user } } = await supabase.auth.getUser()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!user) return { success: false, error: 'Non authentifié' }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data: employe } = await supabase
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .from('employes')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .select('role')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .eq('auth_user_id', user.id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .single()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!employe || !['admin', 'gestionnaire'].includes(employe.role)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return { success: false, error: 'Permission refusée' }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { error } = await supabase
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .from('modules')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .delete()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .eq('id', moduleId)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (error) return { success: false, error: error.message }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return { success: true, data: undefined }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  /** Réordonne les modules d'une formation */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  export async function reorderModules(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    updates: { id: string; ordre: number }[]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ): Promise<ActionResult> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const supabase = await createClient()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data: { user } } = await supabase.auth.getUser()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!user) return { success: false, error: 'Non authentifié' }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const { data: employe } = await supabase
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .from('employes')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .select('role')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .eq('auth_user_id', user.id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .single()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!employe || !['admin', 'gestionnaire'].includes(employe.role)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return { success: false, error: 'Permission refusée' }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Upsert en masse
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const promises = updates.map(({ id, ordre }) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            supabase.from('modules').update({ ordre }).eq('id', id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const results = await Promise.all(promises)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const failed = results.find(r => r.error)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (failed?.error) return { success: false, error: failed.error.message }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return { success: true, data: undefined }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
